"""One-shot root adjudication of eight differing blind boxes on scan 047."""
from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]; p='149_scan047'
rp=R/'records'/f'{p}.json'; r=json.loads(rp.read_text())
pp=R/'pages'/f'{p}.tex'; s=pp.read_text()
cmp={x['box']:x for x in json.loads((R/'second'/f'{p}_comparison.json').read_text())}
f={b:x['first'] for b,x in cmp.items()}
repls=[('regarder des tels modèles',r'regarder \unsure{de|des} tels modèles'),(r'\unsure{de tels}',r'\unsure{de tels|dont le|dans le}'),(r'\unsure{homomorphisme}',r'\unsure{homph}'),(r'\deleted{il suffit}',r'\deleted{il \unsure{suffit}}'),(r'\unsure{se plonge|est plongé}',r'\unsure{se|est} plonge'),('connaît','connait')]
for old,new in repls:
    assert old in s,old
    s=s.replace(old,new)
    for b in f:f[b]=f[b].replace(old,new)
pp.write_text(s)
def coords(b):return next(x['coords'] for x in r['audit_boxes'] if x['box']==b)
r['rows'][2].update(place='First de/des before tels modèles',final=r'\unsure{de|des}',against_C=True,against_H=False,scan_shows='The d loop and low e are clear. The long terminal course favours de; its small dark return could still be s, so de becomes primary with des retained. This is not decided by grammar.',crop=f'crops/{p}_second_B04.jpg',box=coords('B04'),confidence='medium')
r['rows'][11].update(final=r'\deleted{\unsure{de tels|dont le|dans le}}',scan_shows='The initial d loop and later tall l loop survive two parallel strikes. The obscured low sequence can support de tels or dont le/dans le; keep the first reading while making the blind alternatives explicit.',crop=f'crops/{p}_second_B07.jpg',box=coords('B07'))
r['rows'][15].update(final=r'cet \unsure{homph}',against_C=True,kind='abbreviation expanded or spelling modernised',error_category='Abbreviations expanded, spelling modernised',scan_shows='Cet is clear. The compact following group has an h upright, low o/m strokes, a p-like descender and another tall h course, with a compressed terminal return at the edge. It does not supply the full homomorphisme sequence. Retain doubtful dotless homph without expansion.',crop=f'crops/{p}_second_B07.jpg',box=coords('B07'),confidence='medium')
for place,crop,box in [('Before the homology formula, quand on connait seulement',f'crops/{p}_audit_connait_detail.jpg',[940,1430,1215,1575]),('After VA, quand on connait son action',f'crops/{p}_second_B11.jpg',coords('B11'))]:
    r['rows'].append(dict(place=place,C='connaît',H='connaît',final='connait',against_C=True,against_H=True,kind='abbreviation expanded or spelling modernised',error_category='Abbreviations expanded, spelling modernised',scan_shows='The word has no circumflex stroke above the a/i course. The small isolated dot does not form an angled accent. The literal unaccented spelling is retained; both occurrences on this leaf were checked independently.',crop=crop,box=box,confidence='high',marked_in_H=False,consequential=False))
for d in r['decisions']:
    if d['id']=='M1112':d.update(reading=r'\unsure{se|est} plonge',ink='The opening short group is overdrawn and admits se/est. The following p-l-o-n-g-e course is legible, with no detached accent over its final e; narrow the doubt to the short group.',crop=f'crops/{p}_second_B10.jpg',box=coords('B10'))
for d in r['doubts']:
    if d['place']=='Cancelled phrase after first B_U→B_V':d.update(reading=r'\unsure{de tels|dont le|dans le}',alternatives='de tels | dont le | dans le',reason='Two long strikes obscure the central low letters; the initial d and later l loop do not settle the word division.')
    if d['place']=='Compressed word after cet at right edge':d.update(reading=r'\unsure{homph}',alternatives='exact abbreviated terminal strokes unresolved',reason='The compact h, low o/m, p-like descender and h course are visible. No full homomorphisme sequence can be separated; the short form remains unexpanded and doubtful.')
    if d['place']=='M1112, phrase after dès que V':d.update(reading=r'\unsure{se|est} plonge',alternatives='se | est',reason='Retracing obscures the short first word. The following plonge is clear and has no final accent, so uncertainty is narrowed to the opening group.')
r['doubts'].extend([dict(place='First de/des before tels modèles',reading=r'\unsure{de|des}',alternatives='des',confidence='medium',reason='The low e and its long tail favour de; a small terminal return could be a joined s.'),dict(place='Cancelled word following il',reading=r'\unsure{suffit}',alternatives='internal letters under the strike unresolved',confidence='medium',reason='The tall double-f courses support suffit, but the horizontal cancellation and raised replacement hide the low middle letters.')])
r['abbreviations'].append(dict(form=r'\unsure{homph}',expansion='homomorphisme, probably; the written compact form is not expanded in the transcription'))
r['crops'].append(dict(file=f'crops/{p}_audit_connait_detail.jpg',box=[940,1430,1215,1575],reason='Root follow-through from the blind accent disagreement: check the earlier occurrence of connait independently.'))
r['hand_log'].append(dict(habit='The two occurrences of connait have no visible circumflex.',places='149_scan047, before the homology display and after VA',scope='Both occurrences inspected independently; no general modernization rule is applied.',witness_errors='Both witnesses supply connaît at both places.'))
for h in r['hand_log']:
    if 'Short forms can differ' in h['habit']:h['places']='149_scan047, K ext., doubtful homph, du hom., sans hyp, final hom'
r['notes']=r['notes'].replace('Literal des tels, passons pour le moment sur cette situation mixte, and son action are retained.','The first de/des before tels remains doubtful with de primary; the later des after Si U,V sont is retained. Passons pour le moment sur cette situation mixte and son action are retained.').replace('Compressed homomorphisme reaches the edge and has a new doubt.','The compressed word at the right edge is retained as doubtful dotless homph, without expansion.').replace('M1112 retains se plonge|est plongé because its opening is overdrawn.','M1112 is narrowed to se|est before clear unaccented plonge because only the opening is overdrawn.')
r['notes']+='\n\n[Blind audit] All eight differing boxes were decided on their crops; the five blind details were also inspected. The isolated point after the closing modèles quotes has no secure punctuation attachment and is not added. The cancelled de tels remains primary with dont le/dans le alternatives. The full homology expression was reread: the short looped coefficient subscripts match the local ell notation, the second H index remains 1|n, and its connector remains headless. The raised sans hyp has no separate l/apostrophe before its h and remains resolved; the underlying suffit gains a local doubt. The low joined u of du and its later real abbreviation stop remain. Types étales is retained: the angular descending y and following p, then accented e/t/a/l/e/s, exclude the blind topos Abs reading. The two knows-verb occurrences both lack a circumflex, checked separately on B11 and the additional crop (940,1430,1215,1575); both now read connait. No new mathematical check was undertaken.'
inks={
'B03':'Paired closing quotes are followed by an isolated pin-point, without a secure punctuation attachment; it is not added as a full stop. The curved leader places anabéliens after élémentaires. The blind comma and voire are extra edge context already present in the full page.',
'B04':'The d loop and low e are plain. The terminal line favours de but its dark return could still be s, so change the first reading to de|des. K(pi,1), the cancelled de nombres and raised K ext. remain as written.',
'B05':'Q has a reinforced internal tail, consistent with the established double-struck rendering. One horizontal dash follows; single versus double source-code hyphens encode its typography. Three actual dots precede the closing parenthesis; ldots versus literal dots is formatting. The lower des remains distinct from the shorter first de/des.',
'B07':'The B_U-to-B_V shaft has a two-arm head; arrow length and Q font are conventional. Two strikes obscure the middle of the cancelled phrase: initial d and tall l admit de tels/dont le/dans le. The V/U overwriting remains locally unresolved. The compact word after cet has h, low o/m, a p-like descender and tall h, without the full homomorphisme course; change to doubtful dotless homph. Both supplementary B07 details were inspected.',
'B08':'The whole formula was reread. The first H index is isolated 1; the second joins the upright in an n-like arch, leaving 1|n with 1 first under the local homology notation. The small open loops after the Z letters match the local ell coefficient form; an e is not independently distinguished. Both Z letters have reinforced diagonal courses, both U/V bars remain, and the middle stroke has no head. The lower detached dots have no formula attachment. Display delimiters, font and dash length are formatting.',
'B09':'The low joined u after d supports du, not des; the real stop after hom is retained. In the cancellation the f stems survive, but the low interior is crossed, so add a local doubt to suffit. The raised hyp begins with its h upright, without a separate l and apostrophe; retain sans hyp and its absence of a stop. The Q form is consistent with the established font. The supplementary revision detail was inspected.',
'B10':'The short opening group is retraced and admits se/est. The following plonge has a clear final e without an accent. Narrow the mark to se|est before plonge, without pretending the initial group is resolved.',
'B11':'The i region of connait has a single dot and no angled circumflex; remove the supplied accent. The angular y descends before the p in types. The following word begins with accented e, then tall t, low a, tall l and terminal es: retain étales rather than Abs/Ab. Three separate dots and the closing parenthesis agree. Both supplementary B11 details were inspected; the other occurrence of connait was independently checked on the additional saved crop and corrected too.'}
reviews=[]
for b,x in cmp.items():
    if not x['different']:continue
    changed=f[b]!=x['first']
    reviews.append(dict(box=b,decision=('mark doubt' if b in ('B04','B09','B10') else 'correct') if changed else ('formatting' if b=='B05' else 'keep'),final=f[b],ink=inks[b],changed=changed))
(R/'second'/f'{p}_review.json').write_text(json.dumps({'box_reviews':reviews},ensure_ascii=False,indent=2)+'\n')
rp.write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n')
